-- Draft DDL reverse-engineered from the live catalog: PostgreSQL purchasing_db
-- Generated by src/reverse_engineer.py (synthetic data, seed 472). Inferred links are comments only.

CREATE TABLE branch (
  branch_id SMALLINT,
  branch_label TEXT,
  PRIMARY KEY (branch_id)
);

CREATE TABLE goods_receipt (
  grn_no TEXT,
  po_no TEXT,
  received_at TIMESTAMP,
  status TEXT,
  updated_at TIMESTAMP,
  PRIMARY KEY (grn_no),
  FOREIGN KEY (po_no) REFERENCES purchase_order (po_no)
);

CREATE TABLE grn_line (
  grn_no TEXT,
  line_no SMALLINT,
  vendor_item_code TEXT,
  boxes_received NUMERIC(8, 2),
  cost_per_box NUMERIC(12, 2),
  updated_at TIMESTAMP,
  PRIMARY KEY (grn_no, line_no),
  FOREIGN KEY (grn_no) REFERENCES goods_receipt (grn_no),
  FOREIGN KEY (vendor_item_code) REFERENCES vendor_item (vendor_item_code)
);

CREATE TABLE purchase_order (
  po_no TEXT,
  supplier_id INTEGER,
  branch_id SMALLINT,
  ordered_at TIMESTAMP,
  currency CHAR(3),
  updated_at TIMESTAMP,
  PRIMARY KEY (po_no),
  FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id),
  FOREIGN KEY (branch_id) REFERENCES branch (branch_id)
);

CREATE TABLE supplier (
  supplier_id INTEGER,
  supplier_name TEXT,
  country TEXT,
  is_import BOOLEAN,
  PRIMARY KEY (supplier_id)
);

CREATE TABLE vendor_item (
  vendor_item_code TEXT,
  supplier_id INTEGER,
  description TEXT,
  strips_per_box INTEGER,
  PRIMARY KEY (vendor_item_code),
  FOREIGN KEY (supplier_id) REFERENCES supplier (supplier_id)
);
